-- LENZI 0002 — core relational schema
-- Conventions:
--   * UUID primary keys generated by pgcrypto.gen_random_uuid()
--   * timestamptz everywhere; the product renders Africa/Dar_es_Salaam
--   * TZS amounts use numeric(12,2)
--   * geography points use WGS84 (SRID 4326)
--   * financial/ride audit history is append-only

create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  role public.user_role not null default 'passenger',
  status public.account_status not null default 'active',
  full_name text,
  phone text,
  email text,
  preferred_language text not null default 'sw' check (preferred_language in ('sw', 'en')),
  avatar_url text,
  emergency_contact_name text,
  emergency_contact_phone text,
  notification_preferences jsonb not null default '{"push": true, "sms": false, "in_app": true}'::jsonb,
  last_seen_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint profiles_phone_format check (phone is null or phone ~ '^\+255[67][0-9]{8}$'),
  constraint profiles_emergency_phone_format check (
    emergency_contact_phone is null or emergency_contact_phone ~ '^\+[1-9][0-9]{7,14}$'
  ),
  constraint profiles_full_name_length check (
    full_name is null or char_length(trim(full_name)) between 2 and 120
  )
);

comment on column public.profiles.phone is 'E.164. Auth also stores the verified number; profile copy is for display.';
comment on column public.profiles.role is 'Only a service-role bootstrap or an existing owner may assign platform_owner.';

create table if not exists public.driver_profiles (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  approval_status public.driver_approval_status not null default 'draft',
  availability public.driver_availability not null default 'offline',
  national_id_last4 char(4),
  date_of_birth date,
  licence_number text,
  licence_expiry date,
  current_location extensions.geography(Point, 4326),
  location_updated_at timestamptz,
  location_consent_at timestamptz,
  last_online_at timestamptz,
  approved_at timestamptz,
  approved_by uuid references public.profiles (id) on delete set null,
  rejection_reason text,
  suspended_reason text,
  rating numeric(3,2) check (rating is null or (rating >= 0 and rating <= 5)),
  total_trips integer not null default 0 check (total_trips >= 0),
  total_offers integer not null default 0 check (total_offers >= 0),
  accepted_offers integer not null default 0 check (accepted_offers >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint driver_profiles_last4 check (national_id_last4 is null or national_id_last4 ~ '^[0-9A-Za-z]{4}$'),
  constraint driver_profiles_licence_expiry check (licence_expiry is null or licence_expiry > date '1950-01-01')
);

create table if not exists public.vehicles (
  id uuid primary key default extensions.gen_random_uuid(),
  driver_id uuid not null references public.driver_profiles (user_id) on delete cascade,
  category public.vehicle_category not null,
  make text,
  model text,
  model_year integer check (model_year is null or model_year between 1980 and extract(year from now())::integer + 1),
  color text,
  plate_number text not null,
  seats smallint not null default 1 check (seats between 1 and 8),
  photo_path text,
  registration_document_path text,
  insurance_document_path text,
  verification_status public.document_status not null default 'pending',
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint vehicles_plate_unique unique (plate_number),
  constraint vehicles_plate_format check (plate_number = upper(plate_number) and char_length(plate_number) between 3 and 20)
);

create table if not exists public.driver_documents (
  id uuid primary key default extensions.gen_random_uuid(),
  driver_id uuid not null references public.driver_profiles (user_id) on delete cascade,
  document_type public.document_type not null,
  storage_path text not null,
  status public.document_status not null default 'pending',
  reviewed_by uuid references public.profiles (id) on delete set null,
  reviewed_at timestamptz,
  expires_at date,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint driver_documents_path_unique unique (storage_path)
);

create table if not exists public.service_types (
  id uuid primary key default extensions.gen_random_uuid(),
  code public.vehicle_category not null unique,
  name_sw text not null,
  name_en text not null,
  description_sw text,
  description_en text,
  seats smallint not null default 1 check (seats between 1 and 8),
  active boolean not null default true,
  sort_order smallint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.operating_areas (
  id uuid primary key default extensions.gen_random_uuid(),
  name text not null,
  district text not null,
  region text not null,
  country text not null default 'Tanzania',
  center extensions.geography(Point, 4326) not null,
  radius_m integer not null default 15000 check (radius_m between 500 and 150000),
  boundary extensions.geography(Polygon, 4326),
  timezone text not null default 'Africa/Dar_es_Salaam',
  currency char(3) not null default 'TZS' check (currency = 'TZS'),
  active boolean not null default true,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint operating_areas_name_unique unique (name, district, region)
);

create table if not exists public.fare_rules (
  id uuid primary key default extensions.gen_random_uuid(),
  service_type_id uuid not null references public.service_types (id) on delete restrict,
  operating_area_id uuid not null references public.operating_areas (id) on delete restrict,
  currency char(3) not null default 'TZS' check (currency = 'TZS'),
  base_fare numeric(12,2) not null default 0 check (base_fare >= 0),
  per_km numeric(12,2) not null default 0 check (per_km >= 0),
  per_minute numeric(12,2) not null default 0 check (per_minute >= 0),
  minimum_fare numeric(12,2) not null default 0 check (minimum_fare >= 0),
  waiting_per_minute numeric(12,2) not null default 0 check (waiting_per_minute >= 0),
  cancellation_fee numeric(12,2) not null default 0 check (cancellation_fee >= 0),
  commission_rate numeric(5,4) not null default 0.15 check (commission_rate >= 0 and commission_rate <= 1),
  rounding_increment integer not null default 50 check (rounding_increment > 0 and rounding_increment <= 10000),
  version integer not null default 1 check (version > 0),
  effective_from timestamptz not null default now(),
  effective_to timestamptz,
  active boolean not null default true,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint fare_rules_window check (effective_to is null or effective_to > effective_from),
  constraint fare_rules_version_unique unique (service_type_id, operating_area_id, version)
);

create unique index if not exists fare_rules_one_active_per_service_area
  on public.fare_rules (service_type_id, operating_area_id)
  where active and effective_to is null;

create table if not exists public.platform_settings (
  key text primary key check (key ~ '^[a-z][a-z0-9_.]{2,80}$'),
  value jsonb not null,
  description text,
  is_public boolean not null default false,
  updated_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.promotions (
  id uuid primary key default extensions.gen_random_uuid(),
  code text not null unique,
  name text not null,
  description text,
  discount_type public.discount_type not null,
  discount_value numeric(12,2) not null check (discount_value > 0),
  max_discount numeric(12,2) check (max_discount is null or max_discount > 0),
  minimum_fare numeric(12,2) not null default 0 check (minimum_fare >= 0),
  service_type_id uuid references public.service_types (id) on delete set null,
  operating_area_id uuid references public.operating_areas (id) on delete set null,
  starts_at timestamptz not null default now(),
  ends_at timestamptz,
  usage_limit integer check (usage_limit is null or usage_limit > 0),
  per_user_limit integer not null default 1 check (per_user_limit > 0),
  used_count integer not null default 0 check (used_count >= 0),
  active boolean not null default true,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint promotions_window check (ends_at is null or ends_at > starts_at),
  constraint promotions_code_format check (code = upper(code) and code ~ '^[A-Z0-9_-]{3,32}$')
);

create table if not exists public.rides (
  id uuid primary key default extensions.gen_random_uuid(),
  client_request_id uuid not null,
  passenger_id uuid not null references public.profiles (id) on delete restrict,
  driver_id uuid references public.profiles (id) on delete set null,
  vehicle_id uuid references public.vehicles (id) on delete set null,
  service_type_id uuid not null references public.service_types (id) on delete restrict,
  operating_area_id uuid not null references public.operating_areas (id) on delete restrict,
  fare_rule_id uuid not null references public.fare_rules (id) on delete restrict,
  status public.ride_status not null default 'requested',
  pickup extensions.geography(Point, 4326) not null,
  pickup_address text not null,
  dropoff extensions.geography(Point, 4326) not null,
  dropoff_address text not null,
  estimated_distance_km numeric(8,2) not null default 0 check (estimated_distance_km >= 0),
  estimated_duration_min integer not null default 0 check (estimated_duration_min >= 0),
  estimate_source text not null default 'server_haversine_fallback',
  fare_breakdown jsonb not null default '{}'::jsonb,
  estimated_fare numeric(12,2) not null check (estimated_fare >= 0),
  final_fare numeric(12,2) check (final_fare is null or final_fare >= 0),
  currency char(3) not null default 'TZS' check (currency = 'TZS'),
  commission_amount numeric(12,2),
  driver_earnings numeric(12,2),
  payment_method public.payment_method not null default 'cash',
  promotion_id uuid references public.promotions (id) on delete set null,
  discount_amount numeric(12,2) not null default 0 check (discount_amount >= 0),
  cancellation_fee numeric(12,2) not null default 0 check (cancellation_fee >= 0),
  cancelled_by uuid references public.profiles (id) on delete set null,
  cancellation_reason text,
  requested_at timestamptz not null default now(),
  accepted_at timestamptz,
  arrived_at timestamptz,
  started_at timestamptz,
  completed_at timestamptz,
  cancelled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint rides_client_request_unique unique (passenger_id, client_request_id),
  constraint rides_addresses check (char_length(trim(pickup_address)) between 1 and 300 and char_length(trim(dropoff_address)) between 1 and 300),
  constraint rides_completion_fields check (
    status <> 'completed'
    or (final_fare is not null and completed_at is not null and driver_id is not null and driver_earnings is not null)
  ),
  constraint rides_cancellation_fields check (
    status <> 'cancelled' or cancelled_at is not null
  ),
  constraint rides_driver_required check (
    status not in ('accepted', 'driver_arriving', 'driver_arrived', 'in_progress', 'completed')
    or driver_id is not null
  )
);

create unique index if not exists rides_one_active_per_driver
  on public.rides (driver_id)
  where driver_id is not null
    and status in ('accepted', 'driver_arriving', 'driver_arrived', 'in_progress');

create unique index if not exists rides_one_active_per_passenger
  on public.rides (passenger_id)
  where status in ('requested', 'searching', 'accepted', 'driver_arriving', 'driver_arrived', 'in_progress');

create table if not exists public.ride_offers (
  id uuid primary key default extensions.gen_random_uuid(),
  ride_id uuid not null references public.rides (id) on delete cascade,
  driver_id uuid not null references public.driver_profiles (user_id) on delete cascade,
  vehicle_id uuid not null references public.vehicles (id) on delete restrict,
  status public.ride_offer_status not null default 'pending',
  offered_at timestamptz not null default now(),
  expires_at timestamptz not null,
  responded_at timestamptz,
  created_at timestamptz not null default now(),
  constraint ride_offers_unique unique (ride_id, driver_id),
  constraint ride_offers_expiry check (expires_at > offered_at)
);

create table if not exists public.ride_events (
  id bigint generated always as identity primary key,
  ride_id uuid not null references public.rides (id) on delete cascade,
  event_type text not null check (char_length(event_type) between 2 and 60),
  actor_id uuid references public.profiles (id) on delete set null,
  actor_role text,
  from_status public.ride_status,
  to_status public.ride_status,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.ride_messages (
  id uuid primary key default extensions.gen_random_uuid(),
  ride_id uuid not null references public.rides (id) on delete cascade,
  sender_id uuid not null references public.profiles (id) on delete cascade,
  body text not null check (char_length(trim(body)) between 1 and 1000),
  created_at timestamptz not null default now()
);

create table if not exists public.driver_locations (
  driver_id uuid primary key references public.driver_profiles (user_id) on delete cascade,
  location extensions.geography(Point, 4326) not null,
  heading numeric(5,2) check (heading is null or (heading >= 0 and heading < 360)),
  speed_mps numeric(6,2) check (speed_mps is null or speed_mps >= 0),
  accuracy_m numeric(7,2) check (accuracy_m is null or accuracy_m >= 0),
  recorded_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.payments (
  id uuid primary key default extensions.gen_random_uuid(),
  ride_id uuid not null references public.rides (id) on delete restrict,
  payer_id uuid not null references public.profiles (id) on delete restrict,
  method public.payment_method not null,
  provider public.payment_provider not null default 'cash',
  amount numeric(12,2) not null check (amount >= 0),
  currency char(3) not null default 'TZS' check (currency = 'TZS'),
  status public.payment_status not null default 'pending',
  transaction_reference text,
  provider_reference text,
  idempotency_key text not null,
  failure_code text,
  failure_message text,
  refunded_amount numeric(12,2) not null default 0 check (refunded_amount >= 0),
  paid_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint payments_idempotency_unique unique (idempotency_key),
  constraint payments_refund_limit check (refunded_amount <= amount),
  constraint payments_paid_fields check (status <> 'paid' or paid_at is not null)
);

create table if not exists public.driver_earnings (
  id uuid primary key default extensions.gen_random_uuid(),
  driver_id uuid not null references public.driver_profiles (user_id) on delete restrict,
  ride_id uuid not null unique references public.rides (id) on delete restrict,
  gross_amount numeric(12,2) not null check (gross_amount >= 0),
  commission_amount numeric(12,2) not null check (commission_amount >= 0),
  net_amount numeric(12,2) not null check (net_amount >= 0),
  currency char(3) not null default 'TZS' check (currency = 'TZS'),
  status public.earning_status not null default 'pending',
  available_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint driver_earnings_math check (abs(gross_amount - commission_amount - net_amount) < 0.01)
);

create table if not exists public.payouts (
  id uuid primary key default extensions.gen_random_uuid(),
  driver_id uuid not null references public.driver_profiles (user_id) on delete restrict,
  amount numeric(12,2) not null check (amount > 0),
  currency char(3) not null default 'TZS' check (currency = 'TZS'),
  status public.payout_status not null default 'requested',
  method public.payment_method not null,
  destination_reference text,
  reference text,
  requested_at timestamptz not null default now(),
  processed_at timestamptz,
  processed_by uuid references public.profiles (id) on delete set null,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.ratings (
  id uuid primary key default extensions.gen_random_uuid(),
  ride_id uuid not null unique references public.rides (id) on delete cascade,
  passenger_id uuid not null references public.profiles (id) on delete cascade,
  driver_id uuid not null references public.driver_profiles (user_id) on delete cascade,
  stars smallint not null check (stars between 1 and 5),
  comment text check (comment is null or char_length(comment) <= 1000),
  tags text[] not null default '{}',
  created_at timestamptz not null default now()
);

create table if not exists public.promotion_redemptions (
  id uuid primary key default extensions.gen_random_uuid(),
  promotion_id uuid not null references public.promotions (id) on delete restrict,
  user_id uuid not null references public.profiles (id) on delete cascade,
  ride_id uuid not null unique references public.rides (id) on delete cascade,
  discount_amount numeric(12,2) not null check (discount_amount >= 0),
  created_at timestamptz not null default now(),
  constraint promotion_redemptions_unique unique (promotion_id, user_id, ride_id)
);

create table if not exists public.notifications (
  id uuid primary key default extensions.gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  type text not null,
  title_sw text not null,
  title_en text not null,
  body_sw text not null,
  body_en text not null,
  data jsonb not null default '{}'::jsonb,
  channel public.notification_channel not null default 'in_app',
  read_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists public.notification_deliveries (
  id uuid primary key default extensions.gen_random_uuid(),
  notification_id uuid not null references public.notifications (id) on delete cascade,
  channel public.notification_channel not null,
  status text not null default 'queued' check (status in ('queued', 'sending', 'sent', 'failed', 'skipped')),
  provider_reference text,
  attempts integer not null default 0,
  last_error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.device_tokens (
  id uuid primary key default extensions.gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  token text not null,
  platform text not null check (platform in ('android', 'ios', 'web')),
  last_seen_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  constraint device_tokens_unique unique (token)
);

create table if not exists public.support_tickets (
  id uuid primary key default extensions.gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  ride_id uuid references public.rides (id) on delete set null,
  category text not null check (char_length(category) between 2 and 60),
  subject text not null check (char_length(subject) between 3 and 160),
  description text not null check (char_length(description) between 5 and 4000),
  status public.support_status not null default 'open',
  priority public.support_priority not null default 'normal',
  assigned_to uuid references public.profiles (id) on delete set null,
  resolution text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.support_messages (
  id uuid primary key default extensions.gen_random_uuid(),
  ticket_id uuid not null references public.support_tickets (id) on delete cascade,
  sender_id uuid not null references public.profiles (id) on delete cascade,
  body text not null check (char_length(trim(body)) between 1 and 4000),
  is_internal boolean not null default false,
  created_at timestamptz not null default now()
);

create table if not exists public.saved_places (
  id uuid primary key default extensions.gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  label text not null check (char_length(trim(label)) between 1 and 60),
  address text not null check (char_length(trim(address)) between 1 and 300),
  location extensions.geography(Point, 4326) not null,
  icon text not null default 'star' check (icon in ('home', 'work', 'star')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.admin_audit_logs (
  id bigint generated always as identity primary key,
  actor_id uuid references public.profiles (id) on delete set null,
  actor_role public.user_role,
  action text not null,
  entity_type text not null,
  entity_id text,
  before_data jsonb,
  after_data jsonb,
  ip_address inet,
  user_agent text,
  created_at timestamptz not null default now()
);

comment on table public.admin_audit_logs is 'Append-only. Owner-readable. Populated by triggers and security-definer admin functions.';
comment on table public.rides is 'Financial fields become immutable after completion/cancellation; see private.prevent_ride_tampering.';
comment on table public.driver_locations is 'Current location only. Offline drivers must not be tracked; see update_driver_location.';

-- Generic updated_at maintenance
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array[
    'profiles', 'driver_profiles', 'vehicles', 'driver_documents',
    'service_types', 'operating_areas', 'fare_rules', 'platform_settings',
    'promotions', 'rides', 'driver_locations', 'payments', 'driver_earnings',
    'payouts', 'support_tickets', 'saved_places'
  ]
  loop
    execute format('drop trigger if exists set_updated_at on public.%I', t);
    execute format(
      'create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()',
      t
    );
  end loop;
end $$;

-- Indexes for access paths and geospatial matching
create index if not exists profiles_role_status_idx on public.profiles (role, status);
create index if not exists driver_profiles_approval_idx on public.driver_profiles (approval_status, availability);
create index if not exists driver_profiles_location_gix on public.driver_profiles using gist (current_location);
create index if not exists vehicles_driver_idx on public.vehicles (driver_id) where active;
create index if not exists driver_documents_driver_idx on public.driver_documents (driver_id, status);
create index if not exists operating_areas_center_gix on public.operating_areas using gist (center);
create index if not exists operating_areas_boundary_gix on public.operating_areas using gist (boundary);
create index if not exists rides_passenger_idx on public.rides (passenger_id, created_at desc);
create index if not exists rides_driver_idx on public.rides (driver_id, created_at desc);
create index if not exists rides_status_idx on public.rides (status, created_at desc);
create index if not exists rides_pickup_gix on public.rides using gist (pickup);
create index if not exists rides_dropoff_gix on public.rides using gist (dropoff);
create index if not exists ride_offers_driver_pending_idx on public.ride_offers (driver_id, expires_at) where status = 'pending';
create index if not exists ride_offers_ride_idx on public.ride_offers (ride_id, status);
create index if not exists ride_events_ride_idx on public.ride_events (ride_id, created_at);
create index if not exists ride_messages_ride_idx on public.ride_messages (ride_id, created_at);
create index if not exists driver_locations_gix on public.driver_locations using gist (location);
create index if not exists payments_ride_idx on public.payments (ride_id);
create index if not exists payments_status_idx on public.payments (status, created_at);
create index if not exists driver_earnings_driver_idx on public.driver_earnings (driver_id, status, created_at desc);
create index if not exists payouts_driver_idx on public.payouts (driver_id, status, created_at desc);
create index if not exists notifications_user_idx on public.notifications (user_id, read_at, created_at desc);
create index if not exists notifications_pending_delivery_idx on public.notification_deliveries (status, created_at) where status in ('queued', 'failed');
create index if not exists support_tickets_user_idx on public.support_tickets (user_id, created_at desc);
create index if not exists support_tickets_status_idx on public.support_tickets (status, priority, created_at);
create index if not exists support_messages_ticket_idx on public.support_messages (ticket_id, created_at);
create index if not exists saved_places_user_idx on public.saved_places (user_id, created_at);
create index if not exists admin_audit_logs_created_idx on public.admin_audit_logs (created_at desc);
create index if not exists admin_audit_logs_actor_idx on public.admin_audit_logs (actor_id, created_at desc);
